import Base
import ../bend2/selfhost/ast.bend as Ast
import ../bend2/selfhost/checker_arena.bend as Arena
import ../bend2/selfhost/checker_ir.bend as IR
import ../bend2/selfhost/scope_lookup.bend as Scope

# Owning transport only: fixture descriptors do not certify semantic checking.
type Diagnostic is Data:
  Diagnostic{file: String, span: Ast.SourceSpan, message: String, expected: String, observed: String}
type CheckedProgram is Type:
  CheckedProgram{source: Arena.Arena, modules: List<&2, IR.LoadedModule>, signatures: List<&2, Scope.ArenaGlobal>}
type CheckResult is Type:
  CheckSuccess{program: CheckedProgram}
  CheckFailure{diagnostic: Diagnostic}
type Store is Type:
  Store{source: Arena.Arena, transient: Arena.Arena}
type Published is Data:
  Published{modules: List<&2, IR.LoadedModule>, signatures: List<&2, Scope.ArenaGlobal>}
  Rejected{diagnostic: Diagnostic}
type Fixture is Type:
  Fixture{result: CheckResult, before: U32, after: U32, reused: U32}
type Observation is Data:
  Observation{node: Bool, name: Bool, span: Bool, declaration: Bool, signature: Bool}
type Report is Data:
  Report{observation: Observation, before: U32, after: U32, reused: U32}

def span() -> Ast.SourceSpan:
  Ast.SpanOf{"fixture.bend", 7n, 19n}

def span_ok(value: Ast.SourceSpan) -> Bool:
  match value:
    case Ast.SpanOf{file, begin, end}:
      Bool.and(String.eq(file, "fixture.bend"), Bool.and(Nat.is_eq(begin, 7n), Nat.is_eq(end, 19n)))

# The failure arm affine-drops both owners; success transfers only source.
def finish(store: Store, published: Published) -> CheckResult:
  match store:
    case Store{source, _}:
      match published:
        case Published{modules, signatures}: CheckSuccess{CheckedProgram{source, modules, signatures}}
        case Rejected{diagnostic}: CheckFailure{diagnostic}

# Logically readonly: Array access still consumes and returns the owner.
def read_node_result(modules: List<&2, IR.LoadedModule>, signatures: List<&2, Scope.ArenaGlobal>, result: Arena.Arena & Arena.Node) -> CheckedProgram & Arena.Node:
  match result:
    case Tuple{source, node}: (CheckedProgram{source, modules, signatures}, node)

def read_node(program: CheckedProgram, id: U32) -> CheckedProgram & Arena.Node:
  match program:
    case CheckedProgram{source, modules, signatures}:
      read_node_result(modules, signatures, Arena.get_node(source, id))

def observe_name(node_ok: Bool, span: Bool, declaration: Bool, signature: Bool, result: Arena.Arena & String) -> Observation:
  match result:
    case Tuple{_, name}: Observation{node_ok, String.eq(name, "Fixture.target"), span, declaration, signature}

def observe_ref(declaration: Bool, signature: Bool, outer_span: Bool, result: Arena.Arena & Arena.Node) -> Observation:
  match result:
    case Tuple{source, node}:
      match node:
        case Arena.TermRef{key, source_span}: observe_name(True{}, Bool.and(outer_span, span_ok(source_span)), declaration, signature, Arena.name_text(source, key))
        case _: Observation{False{}, False{}, False{}, declaration, signature}

def observe_body(declaration: Bool, signature: Bool, result: CheckedProgram & Arena.Node) -> Observation:
  match result:
    case Tuple{program, node}:
      match program:
        case CheckedProgram{source, _, _}:
          match node:
            case Arena.TermBang{child, source_span}: observe_ref(declaration, signature, span_ok(source_span), Arena.get_node(source, child))
            case _: Observation{False{}, False{}, False{}, declaration, signature}

def signature_ok(signatures: List<&2, Scope.ArenaGlobal>, +body: U32) -> Bool:
  match signatures:
    case Scope.ArenaGlobal{key, _, _, ty, IR.SomeTerm{value}, _} <> Nil{}:
      Bool.and(String.eq(key, "Fixture.value"), Bool.and(U32.is_eq(ty, 0), U32.is_eq(value, body)))
    case _: False{}

# Consumes CheckedProgram; reads published handles, never reconstructs SyntaxTerm.
def lower(program: CheckedProgram) -> Observation:
  match program:
    case CheckedProgram{source, +modules, +signatures}:
      match modules:
        case IR.LoadedModule{_, IR.Module{_, _, IR.DefTop{IR.Definition{key, _, _, IR.DefTerm{+body}, _, source_span}} <> Nil{}}} <> Nil{}:
          observe_body(Bool.and(String.eq(key, "value"), span_ok(source_span)), signature_ok(signatures, body), read_node(CheckedProgram{source, modules, signatures}, body))
        case _: Observation{False{}, False{}, False{}, False{}, False{}}

def consume(fixture: Fixture) -> Report:
  match fixture:
    case Fixture{result, before, after, reused}:
      match result:
        case CheckSuccess{program}: Report{lower(program), before, after, reused}
        case CheckFailure{_}: Report{Observation{False{}, False{}, False{}, False{}, False{}}, before, after, reused}

def fixture_reused(source: Arena.Arena, published: Published, before: U32, after: U32, result: Arena.Arena & U32) -> Fixture:
  match result:
    case Tuple{transient, reused}: Fixture{finish(Store{source, transient}, published), before, after, reused}

def fixture_released(source: Arena.Arena, published: Published, before: U32, result: Arena.Arena & U32) -> Fixture:
  match result:
    case Tuple{transient, after}: fixture_reused(source, published, before, after, Arena.put_node(transient, Arena.TermAbsurd{span()}))

def fixture_count(source: Arena.Arena, published: Published, result: Arena.Arena & U32) -> Fixture:
  match result:
    case Tuple{transient, before}: fixture_released(source, published, before, Arena.node_count(Arena.rewind(transient, Arena.Mark{0, 0, 0, 0, 0, 0})))

def fixture_published(transient: Arena.Arena, result: Arena.Arena & U32) -> Fixture:
  match result:
    case Tuple{source, +body}:
      fixture_count(source, Published{IR.LoadedModule{"Fixture", IR.Module{"fixture.bend", Nil{}, IR.DefTop{IR.Definition{"value", IR.Words{0, 0}, IR.SomeTerm{0}, IR.DefTerm{body}, False{}, span()}} <> Nil{}}} <> Nil{}, Scope.ArenaGlobal{"Fixture.value", "Fixture", "value", 0, IR.SomeTerm{body}, Scope.GlobalDefinition{}} <> Nil{}}, Arena.node_count(transient))

# Finite publication fixture: the only child is already source-owned. No U32 recursion.
def fixture_copy(source: Arena.Arena, result: Arena.Arena & Arena.Node) -> Fixture:
  match result:
    case Tuple{transient, node}: fixture_published(transient, Arena.put_node(source, node))

def fixture_temporary(source: Arena.Arena, result: Arena.Arena & U32) -> Fixture:
  match result:
    case Tuple{transient, id}: fixture_copy(source, Arena.get_node(transient, id))

def fixture_source(result: Arena.Arena & U32) -> Fixture:
  match result:
    case Tuple{source, id}: fixture_temporary(source, Arena.put_node(Arena.empty(), Arena.TermBang{id, span()}))

def fixture_named(result: Arena.Arena & U32) -> Fixture:
  match result:
    case Tuple{source, id}: fixture_source(Arena.put_node(source, Arena.TermRef{id, span()}))

def success() -> Report:
  consume(fixture_named(Arena.name(Arena.empty(), "Fixture.target")))

def failure_result(result: CheckResult) -> Bool:
  match result:
    case CheckSuccess{_}: False{}
    case CheckFailure{Diagnostic{file, source_span, message, expected, observed}}:
      Bool.and(Bool.and(String.eq(file, "fixture.bend"), span_ok(source_span)), Bool.and(String.eq(message, "rejected"), Bool.and(String.eq(expected, "expected"), String.eq(observed, "observed"))))

def failure() -> Bool:
  failure_result(finish(Store{Arena.empty(), Arena.empty()}, Rejected{Diagnostic{"fixture.bend", span(), "rejected", "expected", "observed"}}))

