import Base

type Use is Data:
  Affine{}
  Many{}

type Atom is Data:
  Local{id: U32}
  Capture{slot: U32}
  Word{value: U32}

type Arg is Data:
  Arg{use: Use, value: Atom}

type CheckedArg is Data:
  Erased{source_slot: U32}
  Live{source_slot: U32, use: Use, value: Atom}

type Field is Data:
  Field{identity: U32, slot: U32, use: Use, value: Atom}

type Op is Data:
  Copy{value: Atom}
  Subtract{left: Atom, right: Atom}
  Trace{event: U32, value: Atom}
  Closure{code: U32, captures: List<&2, Arg>}
  Direct{symbol: U32, args: List<&2, Arg>}
  Apply{fn: Atom, arg: Arg}
  Construct{constructor: U32, fields: List<&2, Field>}
  Project{value: Atom, constructor: U32, field: U32, slot: U32}

type Block is Data:
  Return{value: Atom}
  Let{id: U32, op: Op, next: Block}
  TestTag{value: Atom, constructor: U32, yes: Block, no: Block}
  Fail{}

type Code is Data:
  Code{symbol: U32, params: List<&2, U32>, capture_uses: List<&2, Use>, body: Block}

def cat(parts: List<&2, String>) -> String:
  String.join(parts, "")

def atom(value: Atom) -> String:
  match value:
    case Local{id}: cat(["v", U32.show(id)])
    case Capture{slot}: cat(["e[", U32.show(slot), "]"])
    case Word{value}: U32.show(value)

def args(values: List<&2, Arg>) -> String:
  match values:
    case Nil{}: ""
    case Arg{_, value} <> Nil{}: atom(value)
    case Arg{_, value} <> rest: cat([atom(value), ",", args(rest)])

def fields(values: List<&2, Field>) -> String:
  match values:
    case Nil{}: ""
    case Field{_, slot, _, value} <> rest:
      cat([",", U32.show(slot), ":", atom(value), fields(rest)])

def direct_args(values: List<&2, Arg>) -> String:
  match values:
    case Nil{}: ""
    case _: cat([",", args(values)])

def operation(op: Op) -> String:
  match op:
    case Copy{value}: atom(value)
    case Subtract{left, right}: cat(["((", atom(left), "-", atom(right), ")>>>0)"])
    case Trace{event, value}: cat(["($trace.push(", U32.show(event), "),", atom(value), ")"])
    case Closure{code, captures}: cat(["({code:c", U32.show(code), ",env:[", args(captures), "]})"])
    case Direct{symbol, values}: cat(["c", U32.show(symbol), "(null", direct_args(values), ")"])
    case Apply{fn, Arg{_, value}}: cat(["$apply(", atom(fn), ",", atom(value), ")"])
    case Construct{constructor, values}: cat(["({tag:", U32.show(constructor), fields(values), "})"])
    case Project{value, _, _, slot}: cat([atom(value), "[", U32.show(slot), "]"])

def block(body: Block) -> String:
  match body:
    case Return{value}: cat(["return ", atom(value), ";"])
    case Let{id, op, next}: cat(["const v", U32.show(id), "=", operation(op), ";", block(next)])
    case TestTag{value, constructor, yes, no}:
      cat(["if(", atom(value), ".tag===", U32.show(constructor), "){", block(yes), "}else{", block(no), "}"])
    case Fail{}: "throw Error('BIR fail-stop');"

def parameters(ids: List<&2, U32>) -> String:
  match ids:
    case Nil{}: ""
    case id <> rest: cat([",v", U32.show(id), parameters(rest)])

def code(item: Code) -> String:
  match item:
    case Code{symbol, params, _, body}:
      cat(["function c", U32.show(symbol), "(e", parameters(params), "){", block(body), "}\n"])

def codes(items: List<&2, Code>) -> String:
  match items:
    case Nil{}: ""
    case item <> rest: cat([code(item), codes(rest)])

def lower_args(items: List<&2, CheckedArg>) -> List<&2, Arg>:
  match items:
    case Nil{}: Nil{}
    case Erased{_} <> rest: lower_args(rest)
    case Live{_, use, value} <> rest: Arg{use, value} <> lower_args(rest)

def subtract_code() -> Code:
  Code{0, [0, 1], [], Let{2, Subtract{Local{0}, Local{1}}, Return{Local{2}}}}

def partial_code() -> Code:
  Code{1, [0], [Many{}], Let{1, Subtract{Capture{0}, Local{0}}, Return{Local{1}}}}

def returning_code() -> Code:
  Code{2, [0], [], Let{1, Trace{9, Word{0}}, Let{2, Closure{1, [Arg{Many{}, Local{0}}]}, Return{Local{2}}}}}

def finish_fixture() -> Block:
  Let{9, Construct{70, [Field{100, 0, Many{}, Local{2}}, Field{101, 1, Affine{}, Local{4}}, Field{102, 2, Many{}, Local{7}}]},
    TestTag{Local{9}, 70,
      Let{10, Project{Local{9}, 70, 100, 0},
        Let{11, Project{Local{9}, 70, 102, 2},
          Let{12, Subtract{Local{10}, Local{11}},
            Let{13, Construct{71, [Field{110, 0, Many{}, Local{2}}, Field{111, 1, Many{}, Local{4}}, Field{112, 2, Many{}, Local{7}}, Field{113, 3, Many{}, Local{12}}]}, Return{Local{13}}}}}, Fail{}}}

def fixture() -> Block:
  Let{0, Trace{1, Word{20}},
    Let{1, Trace{2, Word{3}},
      Let{2, Direct{0, lower_args([Erased{0}, Live{1, Many{}, Local{0}}, Live{2, Affine{}, Local{1}}])},
        Let{3, Closure{1, [Arg{Many{}, Local{0}}]},
          Let{4, Apply{Local{3}, Arg{Affine{}, Local{1}}},
            Let{5, Direct{2, [Arg{Many{}, Local{0}}]},
              Let{6, Trace{3, Word{4}},
                Let{7, Apply{Local{5}, Arg{Many{}, Local{6}}}, finish_fixture()}}}}}}}}

def program() -> String:
  cat(["const $trace=[];function $apply(f,x){return f.code(f.env,x);}\n",
    codes([subtract_code(), partial_code(), returning_code()]),
    "const result=(()=>{", block(fixture()), "})();console.log(JSON.stringify({result,trace:$trace}));\n"])

def main() -> IO(Unit):
  IO.print(program())

